


export type DeliveryLocationSet = { /** Current member Locations and selection rules. */ "configuration": { "location_ids": Array<string>; }; /** Time the location set was created. Format: date-time. */ "created_at": string; /** Immutable revision used for new quotes. */ "current_delivery_location_set_revision_id": string; /** Stable delivery location set ID. */ "delivery_location_set_id": string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Caller-owned metadata. */ "metadata"?: Record<string, string>; /** Merchant-facing location set name. */ "name": string; /** Current location set lifecycle status. */ "status": "inactive" | "active" | "archived" | "revoked" | (string & {}); /** Time the location set last changed. Format: date-time. */ "updated_at": string; /** Optimistic-concurrency version for location set writes. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version": string; };
